CREATE TABLE payments(id UUID PRIMARY KEY,idempotency_key VARCHAR(100) NOT NULL,request_hash VARCHAR(64) NOT NULL,source_account_id UUID NOT NULL,destination_account_id UUID NOT NULL,amount NUMERIC(19,4) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(30) NOT NULL,failure_reason VARCHAR(255),correlation_id VARCHAR(100),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(idempotency_key));CREATE TABLE outbox_events(id UUID PRIMARY KEY,aggregate_id UUID NOT NULL,event_type VARCHAR(100) NOT NULL,payload TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ);CREATE INDEX idx_outbox_pending ON outbox_events(status,created_at);